try    p = gcp('nocreate');    if isempty(p) || ~strcmpi(p.Type,'processes')        if ~isempty(p), delete(p); end        parpool('Processes');    endcatch    warning('Sin parpool; ejecuto en secuencial');endnRuns  = 3;seeds  = 1:nRuns;results = [];%% ======= Segundo PopsSize2 =======popSize2=220;for k = 1:nRuns    seed = seeds(k);    clc;    fprintf('\n=======================\n')                 fprintf('\n=== Ejecución %d/%d (seed = %d) ===\n', k, nRuns, seed);    fprintf('   PopSize2 = %d\n', popSize2);    fprintf('\n=======================\n')     out = run_EANN(seed, popSize2);    if k == 1        results = repmat(out, nRuns, 1);    end    results(k) = out;end    H1 = results(1).net.dims.H1; H2 = results(1).net.dims.H2; popSize1 = results(1).net.misc.popSize1;popSize2 = results(1).net.misc.popSize2;fname = sprintf('EANN_H1_%02d_H2_%02d_PS1_%03d_PS2_%03d.mat',H1,H2,popSize1,popSize2);save(fname,'results','-v7.3');  % guardado incremental